REPLICAS = ["rack14-db", "rack15-db", "rack16-db"]

def deploy(build):
    for host in REPLICAS:
        push(host, build)   # same build, same minute, every rack

def service_healthy():
    up = [h for h in REPLICAS if ping(h)]
    return len(up) >= 2     # "survives any single failure"
